#include "stdlib/lapack/base/dpbequ.h"
#include "preflight.h"

/**
* Computes scaling factors for a symmetric positive definite band matrix.
*
* @param order  storage layout
* @param uplo   stored triangle
* @param N      number of dense rows and columns
* @param KD     number of stored off-diagonals
* @param AB     read-only compact band matrix
* @param LDAB   leading dimension of the compact view
* @param S      output scales or copied diagonal on failure
* @param SCOND  mutable ratio output, unchanged for a nonpositive diagonal
* @param AMAX   mutable complete diagonal maximum
* @return       INFO or a negative argument position
*/
LAPACK_INT API_SUFFIX(c_dpbequ)( const LAPACK_LAYOUT order, const int uplo, const LAPACK_INT N, const LAPACK_INT KD, const double *AB, const LAPACK_INT LDAB, double *S, double *SCOND, double *AMAX ) {
	dpbequ_envelope envelopeAB;
	dpbequ_envelope envelopeS;
	dpbequ_envelope envelopeSC;
	dpbequ_envelope envelopeAM;
	LAPACK_INT height;
	LAPACK_INT stride1;
	LAPACK_INT stride2;
	LAPACK_INT delta1;
	LAPACK_INT delta2;
	LAPACK_INT high;
	LAPACK_INT info;

	if ( order != LAPACK_ROW_MAJOR && order != LAPACK_COL_MAJOR ) return -1;
	if ( uplo != LAPACK_UPPER_TRIANGLE && uplo != LAPACK_LOWER_TRIANGLE ) return -2;
	if ( N < 0 || N == dpbequ_max() ) return -3;
	if ( KD < 0 || KD == dpbequ_max() ) return -4;
	height = KD+1;
	if ( LDAB < ( order == LAPACK_COL_MAJOR ? height : ( N > 0 ? N : 1 ) ) ) return -6;
	if ( !dpbequ_scalar( SCOND, 0, &envelopeSC ) ) return -8;
	if ( !dpbequ_scalar( AMAX, 0, &envelopeAM ) || dpbequ_overlaps( &envelopeSC, &envelopeAM ) ) return -9;
	if ( N == 0 ) {
		*SCOND = 1.0;
		*AMAX = 0.0;
		return 0;
	}
	if ( AB == NULL ) return -5;
	stride1 = order == LAPACK_COL_MAJOR ? 1 : LDAB;
	stride2 = order == LAPACK_COL_MAJOR ? LDAB : 1;
	if ( !dpbequ_step( height, stride1, &delta1 ) || !dpbequ_step( N, stride2, &delta2 ) || !dpbequ_add( delta1, delta2, &high ) || !dpbequ_physical( AB, 0, 0, high, &envelopeAB ) ) return -5;
	if ( dpbequ_overlaps( &envelopeAB, &envelopeSC ) || dpbequ_overlaps( &envelopeAB, &envelopeAM ) ) return -5;
	if ( S == NULL || !dpbequ_physical( S, 0, 0, N-1, &envelopeS ) ) return -7;
	if ( dpbequ_overlaps( &envelopeS, &envelopeAB ) || dpbequ_overlaps( &envelopeS, &envelopeSC ) || dpbequ_overlaps( &envelopeS, &envelopeAM ) ) return -7;
	info = dpbequ_compute( uplo, N, KD, AB, stride1, stride2, 0, S, 1, 0, SCOND, 0, AMAX, 0 );
	return info == -1 ? -5 : info;
}
